def correct_bracketing(brackets: str):
    count = 0
    for bracket in brackets:
        if bracket == "<":
            count += 1
        elif bracket == ">":
            count -= 1
            if count < 0:
                return False
    return count == 0

def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    else:
        return s[-shift:] + s[:-shift]

def smallest_change(arr):
    n = len(arr)
    changes = 0
    # Compare elements from both ends moving inward
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes

def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if n <= 0:
        return False
    if x == 1:
        return True
    if x < 1:
        return False

    # Check if x is a power of n
    power = 1
    while power < x:
        power *= n
        if power == x:
            return True
        if power > x:
            break

    return power == x

def decimal_to_binary(decimal):
    binary_str = bin(decimal)[2:]  # Convert to binary and remove '0b' prefix
    return "db" + binary_str + "db"

def prime_length(string):
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length**0.5) + 1):
        if length % i == 0:
            return False
    return True

def anti_shuffle(s):
    words = s.split()
    result = []
    for word in words:
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)
    return ' '.join(result)

def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            shift = (2 * 2) % 26  # Rotate by 4 positions
            if char.islower():
                start = ord('a')
            else:
                start = ord('A')
            encrypted_char = chr(start + (ord(char) - start + shift) % 26)
            result.append(encrypted_char)
        else:
            result.append(char)
    return ''.join(result)

def skjkasdkd(lst):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    def sum_of_digits(n):
        s = 0
        while n:
            s += n % 10
            n //= 10
        return s

    max_prime = 0
    for num in lst:
        if is_prime(num):
            max_prime = max(max_prime, num)

    if max_prime == 0:
        return 0
    return sum_of_digits(max_prime)

def move_one_ball(arr):
    if len(arr) == 0:
        return True

    n = len(arr)
    # Check if the array is already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts
    for shift in range(1, n + 1):
        # Perform right shift 'shift' times
        shifted = arr[-shift:] + arr[:-shift]
        # Check if the shifted array is sorted
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True

    return False

def reverse_delete(s, c):
    # Create a new string by keeping only characters in s that are not in c
    result = ''.join(char for char in s if char not in c)

    # Check if the result is a palindrome
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

def max_fill(grid, capacity):
    import math

    total_water = 0
    for row in grid:
        total_water += sum(row)

    # Each bucket can hold 'capacity' units of water
    # So number of bucket trips needed is ceiling of total_water / capacity
    return math.ceil(total_water / capacity)

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    # Start from the second-to-last character and move leftwards
    for i in range(len(word) - 2, -1, -1):
        if word[i] in vowels:
            # Check if the character to the left and right are consonants
            # (not vowels and not spaces, but since we only have letters, check for non-vowels)
            left_char = word[i-1] if i > 0 else None
            right_char = word[i+1] if i < len(word) - 1 else None

            # If both left and right are consonants (not vowels), return this vowel
            if left_char is not None and right_char is not None:
                if left_char not in vowels and right_char not in vowels:
                    return word[i]
    return ""

def solution(lst):
    total = 0
    for i in range(0, len(lst), 2):  # even positions (0-indexed)
        if lst[i] % 2 == 1:  # odd number
            total += lst[i]
    return total

def valid_date(date):
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    try:
        month = int(parts[0])
        day = int(parts[1])
        year = int(parts[2])
    except ValueError:
        return False

    if month < 1 or month > 12:
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_days = 31
    elif month in [4, 6, 9, 11]:
        max_days = 30
    else:  # month == 2
        max_days = 29  # We'll handle leap year later if needed

    if day < 1 or day > max_days:
        return False

    # Check for leap year for February
    if month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            max_days = 29
        else:
            max_days = 28
        if day < 1 or day > max_days:
            return False

    return True

def prod_signs(arr):
    if len(arr) == 0:
        return None

    product_of_signs = 1
    sum_of_magnitudes = 0

    for num in arr:
        if num == 0:
            product_of_signs = 0
            break
        elif num > 0:
            product_of_signs *= 1
            sum_of_magnitudes += num
        else:  # num < 0
            product_of_signs *= -1
            sum_of_magnitudes += -num

    if product_of_signs == 0:
        return 0
    else:
        return product_of_signs * sum_of_magnitudes

def digits(n):
    product = 1
    has_odd = False
    for digit in str(n):
        d = int(digit)
        if d % 2 == 1:
            product *= d
            has_odd = True
    return product if has_odd else 0

def can_arrange(arr):
    if len(arr) <= 1:
        return -1

    for i in range(1, len(arr)):
        if arr[i] <= arr[i-1]:
            return i

    return -1
